from pathlib import Path
import html,json,shutil
ROOT=Path(__file__).resolve().parent;PROJECT=ROOT.parents[3]
D=json.loads((ROOT/'assembly-data.json').read_text());B=json.loads((ROOT/'bom-p4.json').read_text())
def esc(x):return html.escape(str(x))
def table(rows,heads=None):return '<table>'+(''.join('<th>'+esc(h)+'</th>' for h in heads) if heads else '')+''.join('<tr>'+''.join('<td>'+esc(v)+'</td>' for v in r)+'</tr>' for r in rows)+'</table>'
def stack(layers,label):
    colors={'PETG':'#248b91','木':'#c69a65','铝':'#b9c6ce','PP':'#e8e8dd','PET':'#d9d7bc','型材':'#46565e'}
    out='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 450 270" class="stack"><text x="12" y="21" font-size="15" fill="#315369">'+esc(label)+'</text>'
    yy=45
    for name,t,mat in layers:
        h=max(15,min(35,t*4));out+=f'<rect x="25" y="{yy}" width="130" height="{h}" fill="{colors[mat]}" stroke="#66808d"/><text x="175" y="{yy+h/2+5}" font-size="14" fill="#294552">'+esc(name)+' '+str(t)+'mm</text>';yy+=h
    out+=f'<path d="M90 31V{yy+22}" stroke="#9b7a3f" stroke-width="6"/><rect x="79" y="29" width="22" height="7" fill="#9b7a3f"/><path d="M80 {yy+13}h20v8H80Z" fill="#9b7a3f"/><text x="12" y="{min(257,yy+46)}" font-size="12" fill="#627d8b">穿过顺序示意；薄层放大，非等比剖面。</text></svg>'
    return out
def camstack():return '''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 450 230" class="stack"><text x="12" y="22" font-size="15" fill="#315369">两端分别锁进8mm内内隔柱</text><rect x="35" y="60" width="130" height="12" fill="#37665a"/><rect x="76" y="72" width="48" height="65" fill="#bca364"/><rect x="35" y="137" width="130" height="32" fill="#248b91"/><path d="M100 38V99M100 191V119" stroke="#805f2e" stroke-width="5"/><path d="M90 37h20M90 192h20" stroke="#805f2e" stroke-width="8"/><g fill="#294552" font-size="14"><text x="185" y="60">PCB侧：M2×5候选</text><text x="185" y="99">隔柱8mm，约8只/双摄</text><text x="185" y="151">打印背板4mm</text><text x="185" y="187">背板侧：M2×8候选</text><text x="12" y="220">不能用一根长螺钉穿过全部；两端不可互相顶碰。</text></g></svg>'''
pages=[]
def sheet(title,subtitle,left,right):
    n=len(pages)+1;pages.append(f'<section class="sheet"><header><small>BEANLENS H3-P4 / 2026.10.22</small><h1>{title}</h1><p>{subtitle}</p></header><main><div>{left}</div><aside>{right}</aside></main><footer>{n:02} / 10　单位mm；外形与候选孔位仅经主机检查，未实打／承载。打印件使用P1/P2原文件，切片沿用P3。</footer></section>')
def fig(src,caption):return f'<figure><img src="{src}"><figcaption>{caption}</figcaption></figure>'
def connection(id,stacksvg,extra=''):
    j=next(j for j in D['joints'] if j['id']==id)
    return '<h2>'+j['chain']+'</h2><div class="fast">'+('<br>'.join(j['fasteners']))+'</div><ol>'+''.join('<li>'+s+'</li>' for s in j['steps'])+'</ol>'+stacksvg+'<p class="note">'+(j['note'] or '对照孔位纸样先松装；螺长核垫片、螺母与槽底。')+'</p>'+extra
heights=[('裸框','220×240×460'),('底木板','Z22–28'),('收豆杯参考','Z28–108，出口160'),('工作木台','Z180–186'),('相机木条','Z234–240'),('双摄水平光轴','Z260'),('后横梁','Z298–318'),('闸盒下盖／上盖','321–324／326.3–329.3'),('舵机轴心','170 / 180 / 331'),('PP顶环／顶框','440–443／440–460')]
sheet('整机组装：先认承重路径','黑2020承重；5件海洋板保留；打印件通过法兰、底脚或隔柱固定。',fig('shots/whole.png','整机组装，遮光片透明显示仅为看内部。')+'<p>各图均使用同一坐标与实体尺寸；前为小Y，X左右、Z向上。电源、降压和PWM缓冲在机外低压盒，不挤进豆路。机外接线沿用H3。</p>',table(heights,['部位','安装位置'])+'<p>比赛版：单槽、水平双摄、人工单颗；无C6／称重／IR／第二屏。只装9件主打印零件，不把试配片装入整机。</p><p>点击HTML里的连接特写可旋转、拆开与查BOM。固定结构与打印件先试配，再空载与单豆。</p>')
prints=[(r['id'],r['name']) for r in B if r['kind']=='3D打印']
sheet('整机爆炸：9件打印件与保留件','外移距离只为辨认；螺钉、垫片与槽内螺母为无螺纹参考。',fig('shots/exploded.png','打印件为青色，铝板／角码银色，PP浅色，木板木色。')+'<p>不要按爆炸间距下料。打印方向在P3打印包中，装配方向以本图为准。上斗法兰贴PP环下方；下斗法兰贴工作木台上方。</p>',table(prints,['打印编号','零件'])+'<p>P11/P12/P13来自P1；P21–P26来自P2。旧MG金属机身架、PP焊接斗、相机角铝／PP载板不再安装。</p>')
sheet('顶部：打印上斗与PP环怎样连接','两组独立螺钉：斗法兰到PP环；PP环到平连接片与型材底槽。',fig('shots/J06-exploded.png','J06：上斗从PP环下方固定；接座在闸盒上面。')+table([('上斗法兰','104×104×4，孔距92'),('斗孔全局','X64/156，Y74/166'),('平片到PP环','X30/190，Y60/180'),('平片到顶梁底槽','X10/210，Y60/180'),('顶环','176×196×3，中孔80×80')],['对象','尺寸／孔位']),connection('J06',stack([('PP顶环',3,'PP'),('打印法兰',4,'PETG')],'M3×16＋两侧平垫＋防松螺母'))+'<p>J05：4片40×20×2平片，外孔M5向上锁顶深梁底槽；内孔M3×12穿PP，φ9大垫片覆盖φ5.5孔。</p>')
sheet('单槽：后承托、夹层与前封口','闸片只在2.3mm导槽内滑动；夹层螺栓穿侧条，绝不穿铝闸片。',fig('shots/J08-exploded.png','J08：接座／上盖／侧垫条／铝闸片／下盖／承托分开看。')+table([('后承托P30','68×80×3，左前85/160/318'),('移动螺母窗','20×30，左前105/179'),('后横梁P28','180，Z298–318'),('前U片','54×8.3前片＋两16×8.3侧片'),('下短管','内18×14，Z300–321')],['对象','候选尺寸']),connection('J08',stack([('接座底脚',3,'PETG'),('上PP盖',3,'PP'),('PP2＋PET0.3侧条',2.3,'PP'),('下PP盖',3,'PP'),('后承托（仅后孔）',3,'PP')],'后孔M3×25，前孔M3×20'))+'<p>J07：承托后两M5×10锁新增后梁顶槽。前封U片贴盖外缘，下短管外焊下盖；导向、PET与铝片不焊死。</p>')
sheet('舵机：打印架、铝底板与加强角码','固定架不动；一只R16舵臂＋50mm球心距杆驱动闸片。',fig('shots/J09-exploded.png','J09：打印件只替代机身固定架，金属铝板与加强角码保留。')+table([('加强角码','40×40×4，宽20；贴右后柱前面'),('铝板底','153 / 159 / 280.2'),('铝板顶／架底','Z283.2'),('安装耳承面','Z319'),('目标轴心','170 / 180 / 331'),('两球心平面','Z337.5候选')],['对象','位置']),connection('J09',stack([('打印底脚',5,'PETG'),('铝底板',3,'铝')],'底脚M3×12，耳M3×16'))+'<p>铝板到4mm角码M3×12×2；角码到立柱M5×10×2。实际耳高、安装孔、球头中心先量；不能靠螺钉拉弯安装耳。</p>')
sheet('双摄：PCB与打印座如何固定','两镜头水平相向，前30、后210，光轴同为Z260。',fig('shots/J10-exploded.png','J10：PCB与支架之间有8mm隔柱；底脚穿相机木条。')+table([('前相机木条','176×30×6；Y2，顶240'),('后相机木条','176×30×6；Y208，顶240'),('打印脚孔','X84/136，前Y17／后223'),('木条到角铝孔','X30/190，前Y17／后223'),('孔槽范围','24–34方孔距候选，须对实际PCB')],['对象','候选位置']),connection('J10',camstack())+'<p>J04：每条木横条两端一只20宽角铝，M5锁立柱、M3×16穿木条。相机排线不承重，镜筒不夹持。</p>')
sheet('下斗与底板：两处法兰方向不同','下斗落在工作木台上；底木板落在平片上。工作台四只宽40角铝支承。',fig('shots/J12-exploded.png','J12：打印法兰底面Z186，接工作木台顶面。')+table([('下斗安装','90×90法兰，4孔距74'),('下斗孔全局','X73/147，Y83/157'),('工作台方孔','60×60，左前80/90'),('底板孔全局','X60/160，Y30/210'),('底板安装','平片2＋木板6；底22、顶28')],['对象','安装尺寸']),connection('J12',stack([('下斗法兰',4,'PETG'),('工作木台',6,'木')],'M3×16，孔外垫片／螺母'))+'<p>J02：底板4平片先用M5×8锁底框顶槽，再M3×16穿木板。平片避开框角角码；不用旧X30/190底板孔位。</p>')
sheet('BOX：原壳怎样接到木承板','面板前面Y20；压片、软垫与20mm隔柱只固定原壳角边。',fig('shots/J13-exploded.png','J13：螺钉在原壳外侧，不穿屏幕或PCB。')+table([('面板','176×88×6，X22/Y20/Z334'),('板到角铝孔','X30/190，Z350/406'),('隔柱孔','X74/146，Z346/398'),('压片','12×20×2，4片；中孔φ3.4'),('隔柱','M3通孔，长20，4只')],['对象','候选位置']),connection('J13',stack([('铝角压片',2,'铝'),('绝缘通孔隔柱',20,'PP'),('木承板',6,'木')],'M3×35；不经过原壳主体'))+'<p>隔柱、软垫与原壳边缘先试配，保持KEY、TF、CSI与Type-C可达。不把BOX壳外形参考当成已核孔图。</p>')
sheet('照明：灯槽固定在可拆侧PP片上','侧片由角铝接前后木条；前后背景片带镜头孔。透明只为看内部。',fig('shots/J14-exploded.png','J14：灯槽配套卡扣 → 侧片 → 角铝 → 相机木横条。')+table([('两侧片','196×100×2；Y22–218、Z210–310'),('两端避让','木条槽10.5×6.4，Z233.8–240.2'),('右片缺口','后上64×34；Y154起、Z276起'),('背景片','110×47×2，底245；φ24镜头孔'),('后背景缺口','右上30×16，X145起、Z276起')],['对象','避让尺寸']),connection('J14',stack([('配套卡扣底脚',1,'铝'),('侧PP板',2,'PP')],'M3×10；孔型按实购卡扣'))+'<p>侧片与木条角铝用M3×16，侧片／背景角铝用M3×10。灯槽取下再开孔，不穿LED线路；首件实测发热、阴影与曝光。</p>')
